"""Fix E231 violations: missing whitespace after comma."""

import re
import sys
from pathlib import Path

def fix_e231_in_file(filepath):
    """Fix E231 violations in a single file."""
    with open(filepath, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    original = ''.join(lines)
    modified = False

    for i, line in enumerate(lines):
        # Skip comments and strings that might be false positives
        if line.strip().startswith('#'):
            continue

        # Fix missing whitespace after comma: add space after comma if not present
